"""Bounded, replaceable HTTPS transport. No redirects, logs or automatic retry."""
from dataclasses import dataclass, field
import http.client
import json
import math
import socket
import time


@dataclass(frozen=True)
class HttpFailure:
    service: str
    category: str
    status: int | None


_HTTP_CATEGORIES = {
    400: "bad_request",
    401: "unauthorized",
    402: "payment_required",
    403: "forbidden",
    404: "not_found",
    422: "unprocessable_content",
    429: "rate_limited",
}
_HTTP_SERVICES = {"api.github.com": "github", "openrouter.ai": "openrouter"}


class Problem(Exception):
    """Only application-owned error codes; never retain response/header content."""
    def __init__(self, code, status=None, usage=None, *, http_failure=None):
        super().__init__(code)
        self.code = code
        self.status = status
        # Numeric counters generated by our trusted validation code only.
        # Never attach raw model messages, upstream errors or response bodies.
        self.usage = usage
        self.http_failure = http_failure


def http_problem(code, host, status=None, *, observed_status=None):
    """Keep numeric HTTP status and fixed labels, never the upstream reason/body/headers."""
    service = _HTTP_SERVICES.get(host)
    # An HTTP response may be interrupted while reading. Its status is useful
    # diagnostically, but must not change the caller's failure/reconciliation path.
    numeric = status if observed_status is None else observed_status
    numeric = numeric if type(numeric) is int and 100 <= numeric <= 599 else None
    if code == "network_timeout":
        category = "timeout"
    elif code == "network_error":
        category = "connection_error"
    elif numeric in _HTTP_CATEGORIES:
        category = _HTTP_CATEGORIES[numeric]
    elif numeric is not None and 500 <= numeric <= 599:
        category = "server_error"
    else:
        category = "other_http_error"
    failure = HttpFailure(service, category, numeric) if service is not None else None
    return Problem(code, status, http_failure=failure)


@dataclass(frozen=True)
class HttpReply:
    status: int
    body: bytes = field(repr=False)


class HTTPS:
    def __init__(self, *, connect_timeout=5, read_timeout=30, total_timeout=60,
                 max_response=2 * 1024 * 1024, factory=http.client.HTTPSConnection,
                 clock=time.monotonic):
        self.connect_timeout = connect_timeout
        self.read_timeout = read_timeout
        self.total_timeout = total_timeout
        self.max_response = max_response
        self.factory = factory
        self.clock = clock

    def send(self, host, method, path, headers, body=None):
        if host not in _HTTP_SERVICES or not path.startswith("/"):
            raise Problem("invalid_endpoint")
        connection = response = None
        status = None
        start = self.clock()
        try:
            connection = self.factory(host, timeout=self.connect_timeout)
            connection.connect()
            # HTTPConnection may detach its socket in getresponse() for Connection: close.
            read_socket = connection.sock
            read_socket.settimeout(self.read_timeout)
            connection.request(method, path, body=body, headers=headers)
            response = connection.getresponse()
            status = response.status
            size = response.getheader("Content-Length")
            if size is not None:
                try:
                    if int(size) < 0 or int(size) > self.max_response:
                        raise Problem("response_too_large")
                except ValueError:
                    raise Problem("unexpected_response") from None
            chunks, received = [], 0
            while not response.isclosed():
                remaining = self.total_timeout - (self.clock() - start)
                if remaining <= 0:
                    raise Problem("network_timeout")
                # Do not touch the socket after the response has released its last file reference.
                read_socket.settimeout(min(self.read_timeout, remaining))
                chunk = response.read1(min(65536, self.max_response - received + 1))
                if not chunk:
                    break
                received += len(chunk)
                if received > self.max_response:
                    raise Problem("response_too_large")
                chunks.append(chunk)
            if size is not None and received != int(size):
                raise Problem("incomplete_response")
            return HttpReply(response.status, b"".join(chunks))
        except Problem as error:
            raise http_problem(error.code, host, observed_status=status) from None
        except (TimeoutError, socket.timeout):
            raise http_problem("network_timeout", host, observed_status=status) from None
        except (OSError, http.client.HTTPException):
            raise http_problem("network_error", host, observed_status=status) from None
        finally:
            try:
                if response is not None:
                    response.close()
            finally:
                if connection is not None:
                    connection.close()


def decode(reply):
    try:
        return json.loads(reply.body.decode("utf-8"))
    except (UnicodeError, ValueError, RecursionError):
        raise Problem("unexpected_response") from None


def _safe_output_usage(envelope):
    """Allowlist bounded integer counts only; never log provider text."""
    usage = envelope.get("usage")
    if not isinstance(usage, dict):
        return None
    completion = usage.get("completion_tokens")
    if type(completion) is not int or not 0 <= completion <= 1000000:
        return None
    result = {"completion_tokens": completion}
    prompt = usage.get("prompt_tokens")
    if type(prompt) is int and 0 <= prompt <= 1000000:
        result["prompt_tokens"] = prompt
    total = usage.get("total_tokens")
    if (type(total) is int and completion <= total <= 2000000
            and ("prompt_tokens" not in result or total == prompt + completion)):
        result["total_tokens"] = total
    cost = usage.get("cost")
    if type(cost) in (int, float) and 0 <= cost <= 10 and math.isfinite(cost):
        # Bounded integer micro-USD, rounded up; not an authoritative invoice.
        result["cost_micro_usd"] = math.ceil(cost * 1000000)
    details = usage.get("completion_tokens_details")
    if isinstance(details, dict):
        reasoning = details.get("reasoning_tokens")
        if type(reasoning) is int and 0 <= reasoning <= completion:
            result["reasoning_tokens"] = reasoning
            result["visible_tokens"] = completion - reasoning
    return result


REASONING_CONTROL_CODES = frozenset({
    "not_requested", "disabled_reported_zero", "disabled_unverified",
    "disabled_ignored", "effort_unverifiable", "budget_unverified",
    "budget_reported_within", "budget_reported_exceeded",
})


def _reasoning_control(payload, counts, message):
    """Only observable signals, never retain or expose reasoning content."""
    requested = payload.get("reasoning")
    if not isinstance(requested, dict):
        return "not_requested"
    tokens = counts.get("reasoning_tokens") if counts is not None else None
    if requested.get("enabled") is False or requested.get("effort") == "none":
        fields = ("reasoning", "reasoning_content", "reasoning_details")
        has_reasoning = isinstance(message, dict) and any(message.get(k) for k in fields)
        if (tokens is not None and tokens > 0) or has_reasoning:
            return "disabled_ignored"
        return "disabled_reported_zero" if tokens == 0 else "disabled_unverified"
    budget = requested.get("max_tokens")
    if type(budget) is int and budget >= 0:
        if tokens is None:
            return "budget_unverified"
        return "budget_reported_exceeded" if tokens > budget else "budget_reported_within"
    # A token count cannot prove the provider applied a qualitative effort.
    return "effort_unverifiable"


class OpenRouter:
    MAX_ATTEMPTS = 2
    MAX_RESPONSE = 1024 * 1024

    def __init__(self, key, *, http=None, sleep=time.sleep, max_attempts=2,
                 require_reasoning_usage=False):
        if not isinstance(key, str) or not key or "\n" in key or "\r" in key:
            raise Problem("authentication_error")
        if type(max_attempts) is not int or max_attempts not in (1, 2):
            raise Problem("invalid_request_attempt_limit")
        if type(require_reasoning_usage) is not bool:
            raise Problem("invalid_reasoning_usage_requirement")
        self._key = key
        self.max_attempts = max_attempts
        self.require_reasoning_usage = require_reasoning_usage
        # Bounded numeric telemetry only; no raw model/provider response is retained.
        self.last_usage = None
        self.last_http_elapsed_ms = None
        self.last_reasoning_control = None
        # Larger bounded model completion requires a longer read deadline.
        # GitHub API requests retain their original 5/30/60s limits.
        self.http = http if http is not None else HTTPS(
            read_timeout=480, total_timeout=600, max_response=self.MAX_RESPONSE,
        )
        self.sleep = sleep

    def complete(self, payload):
        self.last_usage = None
        self.last_http_elapsed_ms = None
        self.last_reasoning_control = None
        body = json.dumps(payload, ensure_ascii=True, allow_nan=False).encode("utf-8")
        if len(body) > 262144:
            raise Problem("request_too_large")
        for attempt in range(self.max_attempts):
            started = time.monotonic()
            try:
                reply = self.http.send(
                    "openrouter.ai", "POST", "/api/v1/chat/completions",
                    {"Authorization": "Bearer " + self._key, "Content-Type": "application/json"}, body,
                )
            finally:
                self.last_http_elapsed_ms = min(1000000, max(0,
                    int((time.monotonic() - started) * 1000)))
            if len(reply.body) > self.MAX_RESPONSE:
                raise http_problem("response_too_large", "openrouter.ai", observed_status=reply.status)
            if reply.status == 429 or 500 <= reply.status <= 599:
                if attempt + 1 < self.max_attempts:
                    self.sleep(2 ** attempt)
                    continue
            if reply.status in (401, 403):
                raise http_problem("authentication_error", "openrouter.ai", reply.status)
            if reply.status != 200:
                raise http_problem("http_error", "openrouter.ai", reply.status)
            envelope = decode(reply)
            if not isinstance(envelope, dict) or "error" in envelope:
                raise Problem("external_api_error")
            choices = envelope.get("choices")
            if not isinstance(choices, list) or len(choices) != 1 or not isinstance(choices[0], dict):
                raise Problem("unexpected_response")
            choice = choices[0]
            self.last_usage = _safe_output_usage(envelope)
            message = choice.get("message")
            self.last_reasoning_control = _reasoning_control(payload, self.last_usage, message)
            # Only emit fixed application-owned codes: provider data is untrusted
            # and must never be copied into Actions logs.
            finish_reason = choice.get("finish_reason")
            if finish_reason != "stop":
                diagnostic = {
                    "length": "model_output_limit",
                    "content_filter": "model_content_filter",
                    "error": "model_generation_error",
                }.get(finish_reason) if isinstance(finish_reason, str) else None
                counts = self.last_usage if finish_reason == "length" else None
                raise Problem(diagnostic or "incomplete_response", usage=counts)
            # Provider may ignore optional non-thinking settings. Fail closed
            # if reported usage proves the requested opt-out was not honored.
            if self.last_reasoning_control == "disabled_ignored":
                raise Problem("reasoning_control_ignored", usage=self.last_usage)
            if self.require_reasoning_usage and self.last_reasoning_control == "disabled_unverified":
                raise Problem("reasoning_control_unverified", usage=self.last_usage)
            if not isinstance(message, dict) or message.get("role") != "assistant" or message.get("tool_calls"):
                raise Problem("unexpected_response")
            content = message.get("content")
            if content is not None and not isinstance(content, str):
                raise Problem("unexpected_response")
            return content
        raise Problem("http_error")
